typedef enum {
  NSOCK_LOG_DBG_ALL,
  NSOCK_LOG_DBG,
  NSOCK_LOG_INFO,
  NSOCK_LOG_ERROR,
  NSOCK_LOG_NONE
} nsock_loglevel_t;

struct nsock_log_rec {
  struct timeval time;
  nsock_loglevel_t level;
  const char *file;
  int line;
  const char *func;
  char *msg;
};

enum nsock_loopstatus {
  NSOCK_LOOP_NOEVENTS = 2,
  NSOCK_LOOP_TIMEOUT,
  NSOCK_LOOP_ERROR,
  NSOCK_LOOP_QUIT
};

enum nse_type {
  NSE_TYPE_CONNECT = 0,
  NSE_TYPE_CONNECT_SSL = 1,
  NSE_TYPE_READ = 2,
  NSE_TYPE_WRITE = 3,
  NSE_TYPE_TIMER = 4,
  NSE_TYPE_PCAP_READ = 5,
  NSE_TYPE_MAX = 6,
};

enum nse_status {
  NSE_STATUS_NONE = 0,
  NSE_STATUS_SUCCESS,
  NSE_STATUS_ERROR,
  NSE_STATUS_TIMEOUT,
  NSE_STATUS_CANCELLED,
  NSE_STATUS_KILL,
  NSE_STATUS_EOF,
  NSE_STATUS_PROXYERROR
};

