// Select a default engine: either reset to default (NULL) or pass a common name.
int pick = (int)(*FUZZ_PARAM(unsigned int) % 3);
char *engine = NULL;
if (pick == 1) engine = (char *)"select"; // typical engine name
else if (pick == 2) engine = (char *)"poll";  // another common engine
// Library strdup's the string if non-NULL.
int rc = nsock_set_default_engine(engine);
(void)rc; // Return code may be -1 on error; nsock_pool_new may react later.

// Retrieve the comma-separated engine list; read-only, internal storage.
const char *list = nsock_list_engines();
// Touch a few bytes defensively without modifying to exercise memory.
if (list && list[0] != '\0') {
  volatile char c0 = list[0];
  (void)c0;
}

// Read current log level; value is library-managed.
nsock_loglevel_t lvl = nsock_get_loglevel();
(void)lvl;

// Set a valid log level in range [0,4].
int v = (int)(*FUZZ_PARAM(unsigned int) % 5);
nsock_loglevel_t lvl = (nsock_loglevel_t)v;
nsock_set_loglevel(lvl);

// Run a single non-blocking iteration to avoid blocking the fuzzer.
int timeout_msec = 0; // 0 means one non-blocking loop per API contract
// Call the loop using the actual handle (dereference wrapper pointer).
enum nsock_loopstatus st = nsock_loop(*nsp, timeout_msec);
// Track last loop result and whether an error was observed for this pool.
FUZZ_SET_ATTR_INT(nsp, "last_loopstatus", (int)st);
if (st == NSOCK_LOOP_ERROR) {
  FUZZ_SET_ATTR_INT(nsp, "has_loop_error", 1);
} else {
  FUZZ_SET_ATTR_INT(nsp, "has_loop_error", 0);
}
// Validation: respects non-blocking constraint; pool is returned for continued use.

// Request the loop to quit on next iteration. Safe even if loop not running yet.
nsock_loop_quit(*nsp);
// Mark an intent so a following nsock_loop can observe QUIT.
FUZZ_SET_ATTR_INT(nsp, "quit_requested", 1);
// Validation: passes a valid pool handle by dereferencing the wrapper pointer.

// Only meaningful immediately after nsock_loop returns NSOCK_LOOP_ERROR.
int had_err = FUZZ_GET_ATTR_INT(nsp, "has_loop_error");
if (!had_err) {
  // If no prior error recorded, bail to respect API semantics.
  FUZZ_BAIL();
}
int err = nsock_pool_get_error(*nsp);
// Store last error for observability.
FUZZ_SET_ATTR_INT(nsp, "last_errno", err);
// Validation: ensures semantic precondition via attribute before calling.

// Query SSL handle; may be NULL if SSL is not enabled on this IOD.
nsock_ssl s = nsock_iod_get_ssl(*nsockiod);
FUZZ_SET_ATTR_INT(nsockiod, "has_ssl", s ? 1 : 0);
// Validation: uses a valid iod handle (dereferenced) and records presence as attribute.

// To avoid leaking a referenced SSL session we constrain inc_ref to 0.
// This exercises the code path without requiring a free routine here.
int inc_ref = 0;
nsock_ssl_session sess = nsock_iod_get_ssl_session(*nsockiod, inc_ref);
FUZZ_SET_ATTR_INT(nsockiod, "has_ssl_session", sess ? 1 : 0);
// Validation: respects ownership semantics by not incrementing reference.

// Attach a stable, non-owning pointer. Use the wrapper pointer itself as user data.
void *ud = (void *)nsp;
nsock_pool_set_udata(*nsp, ud);
FUZZ_SET_ATTR_PTR(nsp, "udata", ud);
// Validation: library does not manage memory; attribute enables later consistency check.

// Retrieve previously set user data and assert consistency if we set it.
void *expected = FUZZ_GET_ATTR_PTR(nsp, "udata");
void *got = nsock_pool_get_udata(*nsp);
if (expected) {
  FUZZ_ASSERT(got == expected, "nsock_pool_get_udata mismatch with previously set value");
}
// Validation: only asserts if we previously set an expected value.

// Enable or disable broadcast with a bounded value (0/1) per API.
int optval = (int)(*FUZZ_PARAM(unsigned int) % 2);
nsock_pool_set_broadcast(*nsp, optval);
FUZZ_SET_ATTR_INT(nsp, "broadcast_enabled", optval != 0);
// Validation: optval is constrained to 0/1; pool is returned for reuse.

// Provide a stable NUL-terminated device name. Use a small literal.
const char *dev = "lo"; // loopback is commonly present; library may copy or validate lazily
nsock_pool_set_device(*nsp, dev);
FUZZ_SET_ATTR_STR(nsp, "device", dev);
// Validation: passes dereferenced pool; string lifetime is static.

// Initialize SSL for the pool. Use simple flags (0 or 1) to exercise code paths.
int flags = (int)(*FUZZ_PARAM(unsigned int) % 2); // may include performance hints internally
nsock_ssl_ctx ctx = nsock_pool_ssl_init(*ms_pool, flags);
// Record presence of an SSL context; ownership is tied to the pool, so we don't expose ctx.
FUZZ_SET_ATTR_INT(ms_pool, "has_ssl_ctx", ctx ? 1 : 0);
// Validation: dereferences pool correctly and records capability.

// Initialize DTLS for the pool with simple bounded flags.
int flags = (int)(*FUZZ_PARAM(unsigned int) % 2);
nsock_ssl_ctx ctx = nsock_pool_dtls_init(*ms_pool, flags);
FUZZ_SET_ATTR_INT(ms_pool, "has_dtls_ctx", ctx ? 1 : 0);
// Validation: dereferences pool; attributes track DTLS capability.

// Deleting the pool cancels pending events and invalidates associated IODs.
// Ensure we drop it from the object pool by not returning it as output.
nsock_pool_delete(*nsp);
// Validation: passes the correct handle and respects post-delete unusability.

// Delete a chain created by nsock_proxychain_new. Do not return it as output.
nsock_proxychain_delete(*chain);
// Validation: dereferences wrapper to pass the correct handle; object is dropped.

// Assign a proxy chain to the pool; affects only newly created IODs.
nsock_pool_set_proxychain(*nspool, *chain);
// Validation: both inputs are dereferenced handles; we keep them alive by returning them.

// Return the type of the event; valid only for a real callback event.
// We call to exercise the API; result can be any valid enum value.
enum nse_type t = nse_type(*nse);
FUZZ_SET_ATTR_INT(nse, "last_type", (int)t);
// Validation: event handle is dereferenced; attribute captures observed type.

// Map an event type to its string name. Constrain to valid range [0, NSE_TYPE_MAX-1].
unsigned int raw = *FUZZ_PARAM(unsigned int);
enum nse_type t = (enum nse_type)(raw % 6); // NSE_TYPE_MAX == 6
const char *s = nse_type2str(t);
(void)s;
// Validation: uses only valid enum domain; result pointer treated read-only.

// Query completion status of an event.
enum nse_status st = nse_status(*nse);
FUZZ_SET_ATTR_INT(nse, "last_status", (int)st);
// Validation: dereferences event handle; records status for downstream checks.

// Map an event status to its string name. Constrain to valid range.
unsigned int raw = *FUZZ_PARAM(unsigned int);
// Enum nse_status has values 0..7 in the provided definition.
enum nse_status st = (enum nse_status)(raw % 8);
const char *s = nse_status2str(st);
(void)s;
// Validation: uses valid enum range; returned pointer is treated as static/read-only.

// nse_eof is only meaningful for read-related events. Enforce by checking prior recorded type.
int last_type = FUZZ_GET_ATTR_INT(nse, "last_type");
if (last_type != NSE_TYPE_READ) {
  // Without assurance this event came from a read, bail to respect API.
  FUZZ_BAIL();
}
int eof = nse_eof(*nse);
FUZZ_SET_ATTR_INT(nse, "last_eof", eof);
// Validation: Only called for read-type events; result recorded for downstream checks.

// Only meaningful if the event completed with NSE_STATUS_ERROR. Enforce via attribute.
int last_status = FUZZ_GET_ATTR_INT(nse, "last_status");
if (last_status != NSE_STATUS_ERROR) {
  FUZZ_BAIL();
}
int err = nse_errorcode(*nse);
FUZZ_SET_ATTR_INT(nse, "last_errno", err);
// Validation: Precondition (status==ERROR) enforced; error code captured.

// Obtain the event's unique identifier; valid for any real nsock_event.
nsock_event_id id = nse_id(*nse);
// Track it for potential cancellation correlations.
FUZZ_SET_ATTR_INT(nse, "event_id_low32", (int)(id & 0xFFFFFFFFul));
// Validation: event handle is dereferenced; ID stored for later use if needed.

// Valid only for successful read events. Enforce both type and status.
int last_type = FUZZ_GET_ATTR_INT(nse, "last_type");
int last_status = FUZZ_GET_ATTR_INT(nse, "last_status");
if (last_type != NSE_TYPE_READ || last_status != NSE_STATUS_SUCCESS) {
  FUZZ_BAIL();
}
int nbytes = 0;
char *buf = nse_readbuf(*nse, &nbytes);
// Buffer may be NULL if semantics disallow; however for SUCCESS we expect data (possibly zero-length in edge cases).
// We won't dereference if nbytes <= 0 or buf is NULL.
if (buf && nbytes > 0) {
  volatile char touch = buf[0];
  (void)touch;
}
FUZZ_SET_ATTR_INT(nse, "last_read_nbytes", nbytes);
// Validation: preconditions enforced; buffer treated as read-only and not retained.

// Retrieve the IOD associated with the event. May be NULL for timers, etc.
nsock_iod iod = nse_iod(*nse);
// Record presence/absence; do not export iod if NULL to keep outputs non-null only.
FUZZ_SET_ATTR_INT(nse, "has_iod", iod ? 1 : 0);
// Validation: respects API that iod may be NULL; we keep only the event as output.

// Choose a valid pending_response value in [0,2].
int mode_pick = (int)(*FUZZ_PARAM(unsigned int) % 3);
enum nsock_del_mode mode = (enum nsock_del_mode)mode_pick;
nsock_iod_delete(*iod, mode);
// After deletion, iod becomes invalid; do not return it as an output.

// Attach a stable pointer as user data (use the wrapper pointer itself for determinism).
void *ud = (void *)iod;
nsock_iod_set_udata(*iod, ud);
FUZZ_SET_ATTR_PTR(iod, "udata", ud);
// Validation: library does not free/own this pointer; we track it for later verification.

// Retrieve user data and check consistency if we set it earlier.
void *expected = FUZZ_GET_ATTR_PTR(iod, "udata");
void *got = nsock_iod_get_udata(*iod);
if (expected) {
  FUZZ_ASSERT(got == expected, "nsock_iod_get_udata mismatch with previously set value");
}
// Validation: Asserts only if prior set value is known.

// Retrieve the underlying socket descriptor; do not close it.
int sd = nsock_iod_get_sd(*iod);
FUZZ_SET_ATTR_INT(iod, "last_sd", sd);
// Validation: sd may be -1 if unavailable; we just record it.

// Get unique identifier for the IOD; record low 32 bits for tracking.
unsigned long id = nsock_iod_id(*iod);
FUZZ_SET_ATTR_INT(iod, "iod_id_low32", (int)(id & 0xFFFFFFFFul));
// Validation: Getter invocation only; iod remains alive.

// Query cumulative bytes received on this IOD.
unsigned long rcnt = nsock_iod_get_read_count(*iod);
FUZZ_SET_ATTR_INT(iod, "read_cnt_low32", (int)(rcnt & 0xFFFFFFFFul));
// Validation: Pure getter; value recorded.

// Query cumulative bytes sent on this IOD.
unsigned long wcnt = nsock_iod_get_write_count(*iod);
FUZZ_SET_ATTR_INT(iod, "write_cnt_low32", (int)(wcnt & 0xFFFFFFFFul));
// Validation: Pure getter; value recorded.

// Check whether SSL is active on this IOD.
int is_ssl = nsock_iod_check_ssl(*iod);
FUZZ_SET_ATTR_INT(iod, "is_ssl", is_ssl);
// Validation: Getter; result stored.

// Retrieve peer port in host byte order; -1 if unavailable.
int port = nsock_iod_get_peerport(*iod);
FUZZ_SET_ATTR_INT(iod, "peer_port", port);
// Validation: Getter; value may be -1.

// Must be called before connecting. Enforce using a tracked attribute.
int connected = FUZZ_GET_ATTR_INT((void*)*iod, "connected");
if (connected) { FUZZ_BAIL(); }
// Prepare a sockaddr_storage with an IPv4 loopback address.
struct sockaddr_storage ss;
for (size_t i = 0; i < sizeof(ss); ++i) ((unsigned char*)&ss)[i] = 0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
sin->sin_family = AF_INET;
sin->sin_port = 0; // any local port
sin->sin_addr.s_addr = htonl(0x7F000001u); // 127.0.0.1
size_t sslen = sizeof(struct sockaddr_storage);
int rc = nsock_iod_set_localaddr(*iod, &ss, sslen);
(void)rc;
// Validation: precondition enforced (not connected); structure initialized and size provided.

// Must be called before connecting. Enforce using tracked attribute.
int connected = FUZZ_GET_ATTR_INT((void*)*iod, "connected");
if (connected) { FUZZ_BAIL(); }
// Provide a small IPv4 options buffer (<=40 bytes). Use fuzz string as backing storage.
std::string opts = FUZZ_PARAM_STR();
size_t ipoptslen = opts.size() > 0 ? (opts.size() % 41) : 0; // 0..40 bytes
// If length is zero, still call with a zero-length buffer pointer per API semantics.
void *ipopts_ptr = (void *)(ipoptslen ? opts.data() : opts.data());
int rc = nsock_iod_set_ipoptions(*iod, ipopts_ptr, ipoptslen);
(void)rc;
// Validation: not connected; buffer lifetime extends through call; length bounded.

// Request all fields; API returns 1 if all available, else 0 and sets missing fields.
int protocol = 0;
int af = 0;
struct sockaddr_storage local;
struct sockaddr_storage remote;
size_t socklen = sizeof(struct sockaddr_storage);
// Zero buffers before call.
for (size_t i = 0; i < sizeof(local); ++i) ((unsigned char*)&local)[i] = 0;
for (size_t i = 0; i < sizeof(remote); ++i) ((unsigned char*)&remote)[i] = 0;
int ok = nsock_iod_get_communication_info(*iod, &protocol, &af, (struct sockaddr *)&local, (struct sockaddr *)&remote, socklen);
FUZZ_SET_ATTR_INT(iod, "comm_info_ok", ok);
FUZZ_SET_ATTR_INT(iod, "comm_af", af);
FUZZ_SET_ATTR_INT(iod, "comm_proto", protocol);
// Validation: storage provided for all fields; sizes consistent.

// Assign a NUL-terminated hostname string (may be arbitrary fuzzed content).
std::string h = FUZZ_PARAM_STR();
const char *hostname = h.c_str();
int rc = nsock_iod_set_hostname(*iod, hostname);
(void)rc;
FUZZ_SET_ATTR_STR(iod, "hostname", hostname);
// Validation: valid C-string provided; result ignored as API does not specify return details.

// Create a fresh IOD associated with the provided pool. Use a stable udata pointer (the wrapper itself).
void *ud = (void *)nsockp;
nsock_iod handle = nsock_iod_new(*nsockp, ud);
if (!handle) { FUZZ_BAIL(); }
// Allocate a wrapper slot for the runtime (wrapper points to the handle); runtime assumes ownership of this slot.
nsock_iod *iod = (nsock_iod *)malloc(sizeof(nsock_iod));
if (!iod) { FUZZ_BAIL(); }
*iod = handle;
// Track association and initial state (not connected yet).
FUZZ_SET_ATTR_PTR(iod, "pool", nsockp);
FUZZ_SET_ATTR_INT(iod, "connected", 0);
FUZZ_SET_ATTR_INT(iod, "is_udp", 0);
FUZZ_SET_ATTR_PTR(nsockp, "last_iod", (void*)*iod);
// Validation: ensures handle creation success, provides persistent wrapper, and records attributes.

// Wrap an existing OS socket descriptor. Use sd=0 (STDIN) which is commonly valid; library may special-case it.
int sd = 0;
void *ud = (void *)nsockp;
nsock_iod handle = nsock_iod_new2(*nsockp, sd, ud);
if (!handle) { FUZZ_BAIL(); }
// Allocate a wrapper slot and store the handle.
nsock_iod *iod = (nsock_iod *)malloc(sizeof(nsock_iod));
if (!iod) { FUZZ_BAIL(); }
*iod = handle;
// Track association and initial state (not connected until connect APIs are used).
FUZZ_SET_ATTR_PTR(iod, "pool", nsockp);
FUZZ_SET_ATTR_INT(iod, "connected", 0);
FUZZ_SET_ATTR_INT(iod, "is_udp", 0);
FUZZ_SET_ATTR_PTR(nsockp, "last_iod", (void*)*iod);
// Validation: successfully wraps provided sd, returns persistent wrapper, and records state.

// Initialize an unconnected UDP socket for AF_INET on the given IOD.
int af_pick = (int)(*FUZZ_PARAM(unsigned int) % 2);
int af = af_pick ? AF_INET6 : AF_INET; // choose IPv4 or IPv6
int rc = nsock_setup_udp(*nsp, *ms_iod, af);
(void)rc;
// Mark the IOD as UDP-capable; still not connected to a peer.
FUZZ_SET_ATTR_INT(ms_iod, "is_udp", 1);
FUZZ_SET_ATTR_INT(ms_iod, "connected", 0);
// Validation: passes valid pool+iod and supported AF; retains objects for further use.

// Prepare a destination IPv4 127.0.0.1 with a fuzzed host-order port.
struct sockaddr_storage ss; for (size_t i=0;i<sizeof(ss);++i)((unsigned char*)&ss)[i]=0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
sin->sin_family = AF_INET;
sin->sin_addr.s_addr = htonl(0x7F000001u);
unsigned short port = (unsigned short)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50); // keep timeouts short
nsock_event_id eid = nsock_connect_tcp(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, (struct sockaddr *)&ss, sizeof(struct sockaddr_in), port);
// Record last event id on both pool and iod for potential cancellation.
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Leave connected=0 until event completes.
// Validation: constructs valid sockaddr/port, schedules async connect, tracks event id.

// Prepare IPv4 127.0.0.1 destination for SCTP.
struct sockaddr_storage ss; for (size_t i=0;i<sizeof(ss);++i)((unsigned char*)&ss)[i]=0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
sin->sin_family = AF_INET;
sin->sin_addr.s_addr = htonl(0x7F000001u);
unsigned short port = (unsigned short)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_event_id eid = nsock_connect_sctp(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, (struct sockaddr *)&ss, sizeof(struct sockaddr_in), port);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Validation: schedules SCTP connect with valid sockaddr, bounded timeout, and tracks event id.

// Associate a destination IPv4 127.0.0.1:port with the UDP IOD using OS connect().
struct sockaddr_storage ss; for (size_t i=0;i<sizeof(ss);++i)((unsigned char*)&ss)[i]=0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
sin->sin_family = AF_INET;
sin->sin_addr.s_addr = htonl(0x7F000001u);
unsigned short port = (unsigned short)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
nsock_event_id eid = nsock_connect_udp(*nsp, *nsiod, NULL, (void*)nsiod, (struct sockaddr *)&ss, sizeof(struct sockaddr_in), port);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Mark IOD as logically connected after OS connect().
FUZZ_SET_ATTR_INT(nsiod, "connected", 1);
// Validation: provides valid sockaddr/port, schedules association, and records connection state.

// SSL-over-TCP connect to 127.0.0.1:port with short timeout. No session reuse.
struct sockaddr_storage ss; for (size_t i=0;i<sizeof(ss);++i)((unsigned char*)&ss)[i]=0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
sin->sin_family = AF_INET;
sin->sin_addr.s_addr = htonl(0x7F000001u);
unsigned short port = (unsigned short)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
int proto = (int)(*FUZZ_PARAM(unsigned int) % 2); // e.g., 0=TCP, 1=SCTP per internal convention
nsock_ssl_session sess = NULL;
nsock_event_id eid = nsock_connect_ssl(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, (struct sockaddr *)&ss, sizeof(struct sockaddr_in), proto, port, sess);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Do not mark connected until handshake completes.
// Validation: constructs valid parameters, uses NULL handler/session, and tracks event id.

// Precondition: nsiod must already be connected via TCP/SCTP; enforce via attribute.
int connected = FUZZ_GET_ATTR_INT(nsiod, "connected");
if (!connected) { FUZZ_BAIL(); }
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_ssl_session sess = NULL; // do not retain; library manages when handshake completes
nsock_event_id eid = nsock_reconnect_ssl(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, sess);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Validation: enforces precondition via attribute and schedules SSL (re)handshake with short timeout.

// Read up to nlines (must be positive) with short timeout.
int nlines = (int)(*FUZZ_PARAM(unsigned int) % 16) + 1;
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_event_id eid = nsock_readlines(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, nlines);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
