int nbytes = (int)(*FUZZ_PARAM(unsigned int) % 1024) + 1; // 1..1024
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_event_id eid = nsock_readbytes(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, nbytes);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Validation: nbytes strictly positive; schedules read and records id.

// Read until any data or timeout/error. Use short timeout.
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_event_id eid = nsock_read(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Validation: schedules a generic read with bounded timeout and tracks id.

// Prepare data buffer and length; optionally use -1 to indicate C-string.
std::string s = FUZZ_PARAM_STR();
int choose = (int)(*FUZZ_PARAM(unsigned int) % 3);
const char *data = s.c_str();
int datalen = (choose == 0) ? -1 : (int)(s.size() % 512); // -1 or 0..511
int timeout_msecs = (int)(*FUZZ_PARAM(unsigned int) % 50);
nsock_event_id eid = nsock_write(*nsp, *nsiod, NULL, timeout_msecs, (void*)nsiod, data, datalen);
FUZZ_SET_ATTR_INT(nsp, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
FUZZ_SET_ATTR_INT(nsiod, "last_event_id_low32", (int)(eid & 0xFFFFFFFFul));
// Validation: conforms to datalen semantics (-1 or non-negative) and tracks event id.

// Send to a specific IPv4 address/port with short timeout.
struct sockaddr_storage ss; for (size_t i=0;i<sizeof(ss);++i)((unsigned char*)&ss)[i]=0;
struct sockaddr_in *sin = (struct sockaddr_in *)&ss;
