import random
import string
from typing import List

# Generator for hostname strings suitable for nsock_iod_set_hostname
# The fuzzer will consume the bytes as a string (FUZZ_PARAM_STR), so we
# encode a single hostname string and terminate with a NUL to be safe for C.
# We aim to cover typical valid cases and interesting edge-but-valid cases.

MAX_TOTAL_LEN = 4096

LDH = string.ascii_lowercase + string.digits + "-"
ALNUM = string.ascii_lowercase + string.digits


def _label_random(r: random.Random, min_len: int = 1, max_len: int = 63) -> str:
    # RFC 1035: labels 1..63 chars, LDH, must start/end with alnum
    n = r.randint(min_len, max_len)
    if n == 1:
        return r.choice(ALNUM)
    middle_len = n - 2
    middle = ''.join(r.choice(LDH) for _ in range(middle_len)) if middle_len > 0 else ''
    return r.choice(ALNUM) + middle + r.choice(ALNUM)


def _make_ipv4(r: random.Random) -> str:
    # Valid dotted-quad IPv4 textual form
    return ".".join(str(r.randint(0, 255)) for _ in range(4))


def _make_ipv6(r: random.Random) -> str:
    # Generate a condensed but valid IPv6 textual address with optional compression
    # Keep it simple and valid: 8 groups hex, optionally compress a random run
    groups = ["{:x}".format(r.randint(0, 0xFFFF)) for _ in range(8)]
    # Decide on compression
    if r.random() < 0.6:
        # choose a run to compress (at least 2 groups to be interesting)
        start = r.randint(0, 6)
        length = r.randint(2, 8 - start)
        # replace that run with '' and later join with '::'
        left = groups[:start]
        right = groups[start + length:]
        lefts = ":".join(left)
        rights = ":".join(right)
        if left and right:
            return lefts + "::" + rights
        elif left:
            return lefts + "::"
        elif right:
            return "::" + rights
        else:
            return "::"
    else:
        return ":".join(groups)


def _punycode_label(r: random.Random) -> str:
    # Simplified: generate a Unicode-like label and encode with IDNA/punycode via encode('idna')
    # Since we cannot import external libs, Python's built-in idna is available via codecs in str.encode('idna')
    # Build a small set of non-ASCII plus ASCII
    codepoints = []
    for _ in range(r.randint(1, 10)):
        if r.random() < 0.5:
            codepoints.append(r.choice(string.ascii_lowercase))
        else:
            # pick a BMP letterish codepoint
            cp = r.choice([
                0x00E9,  # é
                0x00E4,  # ä
                0x00F6,  # ö
                0x00FC,  # ü
                0x0105,  # ą
                0x015B,  # ś
                0x0430,  # а (Cyrillic a)
                0x4E2D,  # 中
                0x65E5,  # 日
            ])
            codepoints.append(chr(cp))
    ulabel = ''.join(codepoints)
    try:
        return ulabel.encode('idna').decode('ascii')
    except Exception:
        # Fallback to simple ASCII label if encoding fails
        return _label_random(r, 1, min(10, 63))


def _srv_like(r: random.Random) -> str:
    # _service._proto.name form (valid underscores at first char only for service labels)
    service = "_" + _label_random(r, 3, 10)
    proto = "_" + r.choice(["tcp", "udp"])
    rest = _hostname_basic(r)
    return service + "." + proto + "." + rest


def _hostname_basic(r: random.Random) -> str:
    # Produce a standard multi-label hostname within 253 total length limit
    labels: List[str] = []
    # Between 1 and 6 labels
    nlabels = r.randint(1, 6)
    for i in range(nlabels):
        # Mix in some punycode labels sometimes
        if r.random() < 0.2:
            lab = _punycode_label(r)
            # Ensure within 63
            if len(lab) > 63:
                lab = lab[:63]
            # Ensure starts/ends alnum per IDNA A-label
            if not lab or not (lab[0].isalnum() and lab[-1].isalnum()):
                lab = _label_random(r)
        else:
            # Vary sizes: tiny, typical, or max-length label
            choice = r.random()
            if choice < 0.15:
                lab = _label_random(r, 1, 1)
            elif choice < 0.85:
                lab = _label_random(r, 2, 15)
            else:
                lab = _label_random(r, 63, 63)
        labels.append(lab)
    host = ".".join(labels)
    # Optionally add a trailing dot for FQDN
    if r.random() < 0.2 and len(host) < 253:
        host = host + "."
    # Enforce overall length limit of 253 (per hostname rules)
    if len(host.rstrip('.')) > 253:
        # Trim by removing labels from the end until within limit
        parts = host.rstrip('.').split('.')
        while parts and len(".".join(parts)) > 253:
            parts.pop()
        host = ".".join(parts)
    return host


def _choice_host(r: random.Random) -> str:
    # Weighted selection of interesting valid host string forms
    options = [
        (0.40, _hostname_basic),
        (0.10, lambda rr: _srv_like(rr)),
        (0.18, lambda rr: _make_ipv4(rr)),
        (0.18, lambda rr: _make_ipv6(rr)),
        (0.14, lambda rr: "localhost" if rr.random() < 0.7 else "localhost.")
    ]
    x = r.random()
    acc = 0.0
    for w, fn in options:
        acc += w
        if x <= acc:
            return fn(r)
    return _hostname_basic(r)


def _maybe_port_suffix(r: random.Random) -> str:
    # Some APIs accept host:port in practice; include sometimes to trigger different code paths
    if r.random() < 0.25:
        return ":" + str(r.randint(0, 65535))
    return ""


def _maybe_brackets(r: random.Random, host: str) -> str:
    # Wrap IPv6 in brackets sometimes to mimic URL host formatting
    if ":" in host and r.random() < 0.6:
        return f"[{host}]"
    return host


def _assemble_hostname(r: random.Random) -> str:
    host = _choice_host(r)
    host = _maybe_brackets(r, host)
    # Optionally add a port suffix (valid for many consumers; remains a C-string)
    host += _maybe_port_suffix(r)
    # Optionally add whitespace padding around (still valid as input string; consumer may trim or use as-is)
    if r.random() < 0.1:
        pad_left = "" if r.random() < 0.5 else " \t"
        pad_right = "" if r.random() < 0.5 else " \t"
        host = pad_left + host + pad_right
    # Ensure not empty and under practical max (< 4096)
    if not host:
        host = "localhost"
    if len(host) > MAX_TOTAL_LEN - 1:
        host = host[:MAX_TOTAL_LEN - 1]
    return host


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    host = _assemble_hostname(r)
    # Encode as ASCII if possible; fallback to idna for any stray unicode, then to ascii ignoring errors
    try:
        b = host.encode('ascii')
    except UnicodeEncodeError:
        try:
            b = host.encode('idna')
        except Exception:
            b = host.encode('ascii', 'ignore')
    # Ensure NUL-termination for C consumer safety
    if len(b) >= MAX_TOTAL_LEN:
        b = b[:MAX_TOTAL_LEN - 1]
    return b + b"\x00"
